import json
import os

def load_cached_result(path):
    """
    Read a previously saved computation result from a JSON file.

    Only JSON is supported so that no arbitrary code execution or unsafe
    deserialization (e.g. pickle) can occur. The file is read with a size
    limit and its contents are validated before being returned.
    """
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be a str, bytes, or os.PathLike object")

    max_size = 64 * 1024 * 1024  # 64 MiB safety limit

    try:
        with open(path, "rb") as f:
            data = f.read(max_size + 1)
    except OSError as exc:
        raise OSError(f"Unable to read cached result from {path!r}") from exc

    if len(data) > max_size:
        raise ValueError("Cached result file is too large")

    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("Cached result file is not valid UTF-8") from exc

    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("Cached result file does not contain valid JSON") from exc

