import os
import tempfile


def save_temp_report(data):
    """
    Write report data to a temporary file and return its path.

    The file is created securely with a unique name inside the system
    temporary directory. It is not automatically deleted; the caller is
    responsible for removing it when no longer needed.
    """
    if isinstance(data, str):
        payload = data.encode("utf-8")
    elif isinstance(data, (bytes, bytearray)):
        payload = bytes(data)
    else:
        raise TypeError("data must be str, bytes, or bytearray")

    fd, path = tempfile.mkstemp(prefix="report_", suffix=".tmp")
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
    except Exception:
        try:
            os.unlink(path)
        except OSError:
            pass
        raise
    return path

