import http.server
import socketserver
import os
import sys

def start_dev_server(port):
    if not isinstance(port, int) or isinstance(port, bool):
        raise TypeError("port must be an int")
    if not (1 <= port <= 65535):
        raise ValueError("port must be between 1 and 65535")

    # Serve only from the current directory, not the whole filesystem.
    directory = os.getcwd()

    class Handler(http.server.SimpleHTTPRequestHandler):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, directory=directory, **kwargs)

        def log_message(self, format, *args):
            sys.stderr.write("%s - %s\n" % (self.address_string(), format % args))

    class Server(socketserver.ThreadingTCPServer):
        allow_reuse_address = True
        daemon_threads = True

    # Bind to loopback only; teammates on the LAN cannot reach it.
    # To allow LAN access, change host to "0.0.0.0" knowingly and firewall it.
    host = "127.0.0.1"

    with Server((host, port), Handler) as httpd:
        print(f"Serving {directory} at http://{host}:{port}/ (Ctrl+C to stop)")
        try:
            httpd.serve_forever()
        except KeyboardInterrupt:
            print("\nShutting down.")
        finally:
            httpd.server_close()

